import {t,messageKey,localize} from '../../src/i18n.js';
import BALANCE from '../../src/balance.json' with {type:'json'};
const R=BALANCE.rewards;
import {villageStats} from '../../src/village-stats.js';
import {normalizeConstructionState} from '../../src/construction.js';
import {normalizeCampaign,completeStage} from '../../src/campaign.js';
import {freshSave,SAVE_KEY,buildingCost,BUILDINGS,MAX_BUILDING_LEVEL,WEAPONS} from '../../src/data.js';
export function validSave(s){return !!s&&s.version===1&&Number.isFinite(s.coins)&&s.coins>=0&&s.coins<1e9&&['garage','smithy','greenhouse'].every(k=>Number.isInteger(s.buildings?.[k])&&s.buildings[k]>=0&&s.buildings[k]<=MAX_BUILDING_LEVEL)&&!!s.settings&&typeof s.settings==='object'&&!Array.isArray(s.settings)&&Array.isArray(s.settledRuns)&&normalizeConstructionState(s).ok;}
export let lastLoadStatus={source:'new',recoveredReward:false};
// A recovered settlement owns only checkpoints from that same expedition.
function clearSettledCheckpoints(id,storage){for(const key of ['wandering-hearth:run','wandering-hearth:run:backup'])try{if(JSON.parse(storage.getItem(key))?.run?.id===id)storage.removeItem(key);}catch{}}
export function normalizeSave(s){if(!validSave(s))return null;const base=freshSave(),settings={...base.settings};for(const key of ['sound','contrast','reducedMotion','vibration'])if(typeof s.settings[key]==='boolean')settings[key]=s.settings[key];for(const key of ['volume','bgmVolume','sfxVolume'])if(Number.isFinite(s.settings[key]))settings[key]=Math.max(0,Math.min(1,s.settings[key]));if(['ko','en'].includes(s.settings.language))settings.language=s.settings.language;const result={...base,...s,schemaVersion:2,tutorialSeen:s.tutorialSeen===true,campaign:normalizeCampaign(s),settings,weapon:WEAPONS[s.weapon]?s.weapon:'cannon',settledRuns:[...new Set(s.settledRuns.filter(id=>typeof id==='string'))].slice(-100)};for(const key of ['runs','victories','totalKills','bestTime'])result[key]=Number.isFinite(s[key])&&s[key]>=0?s[key]:0;const construction=normalizeConstructionState(result);if(construction.value)result.construction=construction.value;else delete result.construction;return result;}
export function loadSave(storage=globalThis.localStorage){lastLoadStatus={source:'new',recoveredReward:false};let result=freshSave();for(const key of [SAVE_KEY,SAVE_KEY+':backup'])try{const s=normalizeSave(JSON.parse(storage.getItem(key)));if(s){result=s;lastLoadStatus.source=key===SAVE_KEY?'primary':'backup';break;}}catch{}try{const pending=JSON.parse(storage.getItem(SAVE_KEY+':pending'));if(validSettlement(pending)){const settled=settleRun(result,pending),next=pending.outcome==='victory'?completeStage(settled.save,pending.stageId,pending.time):settled.save;if(saveGame(next,storage)){result=next;lastLoadStatus.recoveredReward=!settled.duplicate;clearSettledCheckpoints(pending.id,storage);storage.removeItem(SAVE_KEY+':pending');}}}catch{}return result;}
export function saveGame(s,storage=globalThis.localStorage){if(!validSave(s))return false;try{const old=storage.getItem(SAVE_KEY);if(old){try{if(validSave(JSON.parse(old)))storage.setItem(SAVE_KEY+':backup',old);}catch{}}storage.setItem(SAVE_KEY,JSON.stringify(s));return true;}catch{return false;}}
function validSettlement(run){return !!run&&typeof run.id==='string'&&run.id.length>0&&['victory','defeat','retreat'].includes(run.outcome)&&['coins','kills','time'].every(k=>Number.isFinite(run[k])&&run[k]>=0&&run[k]<1e7)&&(!run.villageStats||Number.isFinite(run.villageStats.rewardMultiplier)&&run.villageStats.rewardMultiplier>=1&&run.villageStats.rewardMultiplier<=1.5);}
export function commitSettlement(save,run,storage=globalThis.localStorage){if(!validSettlement(run))return {ok:false,save,reward:0};const settled=settleRun(save,run),next=run.outcome==='victory'&&run.stageId?completeStage(settled.save,run.stageId,run.time):settled.save;try{storage.setItem(SAVE_KEY+':pending',JSON.stringify(run));}catch{return {...settled,save:next,ok:false};}const ok=saveGame(next,storage);if(ok)try{clearSettledCheckpoints(run.id,storage);storage.removeItem(SAVE_KEY+':pending');}catch{}return {...settled,save:next,ok};}
export function buyBuilding(s,key){if(!BUILDINGS[key]||s.buildings[key]>=MAX_BUILDING_LEVEL)return {ok:false,reason:t("persistence.113")};const cost=buildingCost(key,s.buildings[key]);if(s.coins<cost)return {ok:false,reason:t("persistence.114")};return {ok:true,save:{...s,coins:s.coins-cost,buildings:{...s.buildings,[key]:s.buildings[key]+1}}};}
export function settleRun(s,run){if(s.settledRuns.includes(run.id))return {save:s,duplicate:true};const base=Math.max(0,run.coins*(run.outcome==='defeat'?R.defeatRetention:1)+run.kills*R.kill+(run.outcome==='victory'?R.victory:0)),multiplier=run.villageStats?.rewardMultiplier??villageStats(s).rewardMultiplier,reward=Math.floor(base*multiplier);return {reward,breakdown:{base:Math.floor(base),bonus:reward-Math.floor(base),multiplier},save:{...s,coins:s.coins+reward,runs:s.runs+1,victories:s.victories+(run.outcome==='victory'?1:0),totalKills:s.totalKills+run.kills,bestTime:Math.max(s.bestTime,run.time),settledRuns:[...s.settledRuns.slice(-49),run.id]}};}

